def with_schema_transform(
    spec: SchemaSpec,
    transform: Callable[[Mapping[str, Any]], Mapping[str, Any]],
    *,
    name: str | None = None,
) -> SchemaSpec:
    """Return a copy of `spec` with an adapter-provided schema transform."""
    transformed = transform(spec.json_schema)
    transformed = {
        key: value
        for key, value in transformed.items()
        if key not in ("$defs", "definitions")
    }
    return replace(
        spec,
        name=spec.name if name is None else name,
        json_schema=transformed,
    )

def with_schema_transform(
    spec: SchemaSpec,
    transform: Callable[[Mapping[str, Any]], Mapping[str, Any]],
    *,
    name: str | None = None,
) -> SchemaSpec:
    """Return a copy of `spec` with an adapter-provided schema transform."""
    transformed = dict(transform(spec.json_schema))
    required = transformed.get("required")
    if isinstance(required, (list, tuple)):
        properties = transformed.get("properties", {})
        transformed["required"] = [
            item for item in required if item in properties
        ]
    return replace(
        spec,
        name=spec.name if name is None else name,
        json_schema=transformed,
    )
